import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    parent = [0]*(n+1)
    depth = [0]*(n+1)
    size = [0]*(n+1)
    visited = [False]*(n+1)

    # BFS to compute parent and depth
    q = deque([1])
    visited[1] = True
    while q:
        u = q.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                depth[v] = depth[u] + 1
                q.append(v)

    # Compute size of subtree rooted at each node
    stack = [(1, False)]
    while stack:
        u, processed = stack.pop()
        if not processed:
            stack.append((u, True))
            for v in adj[u]:
                if v != parent[u]:
                    stack.append((v, False))
        else:
            size[u] = 1
            for v in adj[u]:
                if v != parent[u]:
                    size[u] += size[v]

    # Function to get LCA
    def lca(u, v):
        while u != v:
            if depth[u] > depth[v]:
                u = parent[u]
            else:
                v = parent[v]
        return u

    # Function to get path nodes between u and v
    def get_path_nodes(u, v):
        path = set()
        while u != v:
            if depth[u] >= depth[v]:
                path.add(u)
                u = parent[u]
            else:
                path.add(v)
                v = parent[v]
        path.add(u)
        return path

    # Count the number of paths that include each node
    node_in_path = [0] * (n + 1)
    for a in range(1, n+1):
        for b in range(a+1, n+1):
            path = get_path_nodes(a, b)
            for node in path:
                node_in_path[node] += 1

    # Total number of paths
    total_paths = n * (n - 1) // 2

    # Total number of pairs of paths
    total_pairs = total_paths * (total_paths - 1) // 2

    # Count pairs of paths that share at least one node
    shared_pairs = 0
    for node in range(1, n+1):
        cnt = node_in_path[node]
        shared_pairs += cnt * (cnt - 1) // 2

    # Answer is total_pairs - shared_pairs
    answer = total_pairs - shared_pairs
    print(answer)

if __name__ == "__main__":
    main()
